function statusClass(s){if(['Completed','Ready for Collection','Approved','Resolved','Ready for Handover'].includes(s))return'green';if(['In Repair','Awaiting QC','Under Inspection','Under Review','Inspection Scheduled','Inspection Complete','In Progress'].includes(s))return'blue';if(['Awaiting Customer Approval','Awaiting Estimate','Awaiting Parts','Received','Submitted','Need Information','Partial Approval Pending Customer'].includes(s))return'amber';if(['QC Failed','Estimate Rejected','Cancelled','Rejected','Declined by Customer'].includes(s))return'red';return'gray'}function pill(s){return `<span class="badge ${statusClass(s)}">${esc(s)}</span>`}function byId(id=selected){return S.tickets.find(t=>t.id===id)}function addLog(t,text,actor=USERS[role]){t.activities=t.activities||[];t.activities.push([actor,text,D(0)]);S.logs.unshift({ticket:t.id,actor,text,date:D(0)})}function notify(m){let e=document.createElement('div');e.className='toast';e.textContent=translateText(m);document.getElementById('toasts').appendChild(e);setTimeout(()=>e.remove(),3200)}function navigate(p){page=p;save();render()}function navView(){return NAV[role].map(([g,a])=>`<div class="nav-label">${g}</div><div class="nav-list">${a.map(([n,i])=>`<button class="nav-item ${page===n?'active':''}" data-page="${n}">${ic(i)}<span>${n}</span>${n==='QC Queue'&&S.tickets.some(t=>t.status==='Awaiting QC')?`<b class="nav-count">${S.tickets.filter(t=>t.status==='Awaiting QC').length}</b>`:''}</button>`).join('')}</div>`).join('')}
function login(){return `<div class="login-page"><section class="login-brand-panel"><div class="login-hero"><div class="brand"><div class="brand-mark">${ic('wrench')}</div><div>SERASI<small>SISTEM INFORMASI SERVIS DAN GARANSI ELEKTRONIK</small></div></div><h1>Servis lebih tertata.<br>Pelanggan lebih tenang.</h1><p>Satu sistem untuk menghubungkan pelanggan, teknisi, dan seluruh proses servis perangkat elektronik.</p></div></section><section class="login-form-wrap"><form class="login-form" id="login-form"><div class="eyebrow">PORTAL SERASI</div><h2>Masuk ke SERASI</h2><p>Masukkan email dan kata sandi untuk melanjutkan.</p><div class="field"><label for="login-email">Email</label><input id="login-email" name="email" type="email" autocomplete="username" placeholder="nama@serasi.id" required></div><div class="field"><label for="login-password">Kata sandi</label><input id="login-password" name="password" type="password" autocomplete="current-password" placeholder="Masukkan kata sandi" required></div><button class="btn btn-primary" style="width:100%;justify-content:center;margin-top:8px" type="submit">Masuk ${ic('arrow')}</button><div class="public-claim-entry"><span>Tidak punya akun portal?</span><button type="button" class="text-button" data-action="open-public-claim">Ajukan atau lacak klaim garansi</button></div></form></section></div>`}function doLogin(){let email=document.getElementById('login-email').value.trim().toLowerCase(),password=document.getElementById('login-password').value,entry=Object.entries(LOGIN_ACCOUNTS).find(([,account])=>account.email===email);if(!entry||password!=='serasi2026'){notify('Email atau kata sandi tidak sesuai.');return}role=entry[0];logged=true;page=role==='Customer'?'Track Repair':role==='Technician'?'My Repair Jobs':role==='QC'?'QC Queue':role==='Owner'?'Overview':'Dashboard';selected=role==='Customer'?'SER-2026-001':selected;save();render()}function shell(body){let initials=USERS[role].split(' ').map(x=>x[0]).join('').slice(0,2),email=LOGIN_ACCOUNTS[role].email,label=LOGIN_ACCOUNTS[role].label;return `<div class="shell ${role==='Customer'?'customer-view':''}"><aside class="sidebar"><div class="brand"><div class="brand-mark">${ic('wrench')}</div><div class="brand-word">SERASI<small>SISTEM INFORMASI SERVIS</small></div></div><div class="sidebar-nav">${navView()}</div></aside><main class="main"><header class="topbar"><div class="search">${ic('search')}<input id="global-search" placeholder="Cari tiket, pelanggan, perangkat..." value="${esc(filter)}"></div><div class="top-spacer"></div><button class="top-link notification-trigger ${unreadNotificationCount()?'has-unread':''}" data-action="notifications" aria-label="Notifikasi">${ic('bell')}<span>Notifikasi</span>${unreadNotificationCount()?`<b class="notification-count">${unreadNotificationCount()>9?'9+':unreadNotificationCount()}</b>`:''}</button><div class="profile"><button class="profile-trigger" data-action="profile-menu" aria-expanded="${profileOpen}" aria-label="Buka menu akun"><span class="avatar">${initials}</span><span class="profile-copy"><span class="profile-name">${USERS[role]}</span><span class="profile-role">${label}</span></span><span class="profile-caret">⌄</span></button>${profileOpen?`<div class="profile-menu"><div class="profile-menu-head"><span class="avatar">${initials}</span><span><strong>${USERS[role]}</strong><small>${label}</small></span></div><div class="profile-menu-details"><small>Email akun</small><strong>${email}</strong><small>Peran akses</small><strong>${label}</strong></div><button class="profile-logout" data-action="logout">${ic('back')} Keluar dari akun</button></div>`:''}</div></header><section class="content">${body}</section></main></div>`}function heading(title,sub,buttons=''){return `<div class="heading"><div><div class="eyebrow">${role==='Customer'?'CUSTOMER PORTAL':role.toUpperCase()+' WORKSPACE'}</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${buttons}</div></div>`}function btn(text,act,cls='',extra=''){return `<button class="btn ${cls}" data-action="${act}" ${extra}>${text}</button>`}
function ticketRows(arr){return arr.map(t=>`<tr class="clickable" data-ticket="${t.id}"><td><span class="ticket-id">${t.id}</span><div class="sub-cell">${date(t.received)}</div></td><td><div class="primary-cell">${esc(t.customer)}</div><div class="sub-cell">${esc(t.phone)}</div></td><td><div class="primary-cell">${esc(t.brand)} ${esc(t.model)}</div><div class="sub-cell">${esc(t.category)}</div></td><td>${esc(t.complaint)}</td><td>${esc(t.tech.split(' ')[0])} ${esc(t.tech.split(' ').at(-1)[0])}.</td><td>${pill(t.status)}</td><td>${date(t.due)}</td></tr>`).join('')}
function table(arr,headers=['Ticket / received','Customer','Device','Reported problem','Technician','Status','Due date']){return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${arr.length?ticketRows(arr):`<tr><td colspan="7" class="empty">No matching records found.</td></tr>`}</tbody></table></div>`}
function metric(label,value,foot,icon='ticket'){return `<div class="metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${ic(icon)}</span></div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`}function distribution(tickets=S.tickets){let ss=['Received','Under Inspection','Awaiting Estimate','Awaiting Customer Approval','Estimate Rejected','Awaiting Parts','In Repair','QC Failed','Awaiting QC','Ready for Collection','Completed','Cancelled'],cs=['gray','blue','amber','amber','red','amber','blue','red','blue','green','green','gray'];return `<div class="status-list">${ss.map((s,i)=>{let n=tickets.filter(t=>t.status===s).length,p=Math.max(3,100*n/Math.max(1,tickets.length));return `<div class="status-row"><span>${s}</span><div class="track"><div class="fill ${cs[i]}" style="width:${p}%"></div></div><span class="status-num">${n}</span></div>`}).join('')}</div>`}function barChart(v,l){return `<div class="chart"><div class="bars">${v.map(x=>`<div class="bar-col"><div class="bar" style="height:${Math.max(8,x)}%"></div></div>`).join('')}</div></div><div class="bar-labels">${l.map(x=>`<span>${x}</span>`).join('')}</div>`}
function dashboard(){let t=S.tickets,a=t.filter(x=>!['Completed','Cancelled'].includes(x.status)).length,ap=t.filter(x=>x.status==='Awaiting Customer Approval').length,r=t.filter(x=>x.status==='In Repair').length,q=t.filter(x=>x.status==='Awaiting QC').length,ready=t.filter(x=>x.status==='Ready for Collection').length,rev=t.reduce((n,x)=>n+x.payment,0),late=t.filter(x=>day(x.due)<0&&!['Completed','Cancelled'].includes(x.status)),recent=[...t].sort((x,y)=>y.received.localeCompare(x.received)).slice(0,5),logs=[...(S.logs||[]),...t.flatMap(x=>(x.activities||[]).slice(-1).map(a=>({ticket:x.id,actor:a[0],text:a[1],date:a[2]})))].slice(0,5);return `${heading(role==='Admin'?'Good morning, Maya':'Good morning, '+USERS[role].split(' ')[0],'Here’s what’s happening at your service center today.',btn(`${ic('plus')} New repair`,'new-ticket','btn-primary'))}<div class="grid metrics">${metric('Active tickets',a,'Across all repair stages','ticket')}${metric('Awaiting approval',ap,'Customer estimates to review','clock')}${metric('Repairs in progress',r,'Approved work underway','wrench')}${metric('Awaiting quality control',q,'Ready for inspection','clipboard')}${metric('Ready for collection',ready,'Passed QC · handover pending','handover')}${metric('Revenue recorded',money(rev),`${t.filter(x=>x.paymentStatus==='Paid').length} invoices paid`,'wallet')}</div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Recent service tickets</h2><button data-page="Service Tickets">View all →</button></div>${table(recent)}</div><div class="card"><div class="card-head"><h2>Repair status distribution</h2><span class="badge gray">${t.length} tickets</span></div>${distribution()}</div></div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Overdue repairs</h2><span class="badge ${late.length?'red':'green'}">${late.length} overdue</span></div><div class="card-body">${late.length?late.slice(0,5).map(x=>`<div class="overdue"><div><div class="title">${x.id} · ${esc(x.customer)}</div><div class="detail">${esc(x.brand)} ${esc(x.model)} · ${Math.abs(day(x.due))} days overdue</div></div>${pill(x.status)}</div>`).join(''):`<div class="empty">No overdue repairs. The team is on schedule.</div>`}</div></div><div class="card"><div class="card-head"><h2>Recent activity</h2><span class="badge gray">Live</span></div><div class="card-body"><div class="activity-list">${logs.map(l=>`<div class="activity"><div class="activity-icon">${ic('activity')}</div><div><div class="activity-text"><strong>${esc(l.actor)}</strong> ${esc(l.text)} <span class="ticket-id">${l.ticket}</span></div><div class="activity-time">${date(l.date)}</div></div></div>`).join('')||`<div class="empty">No recent activity.</div>`}</div></div></div></div>`}
function ticketsPage(){let a=S.tickets.filter(t=>(role!=='Customer'||t.customer==='Andi Pratama')&&(role!=='Technician'||t.tech===USERS.Technician)&&(!filter||`${t.id} ${t.customer} ${t.brand} ${t.model}`.toLowerCase().includes(filter.toLowerCase()))&&(statusFilter==='All'||t.status===statusFilter)&&(categoryFilter==='All'||t.category===categoryFilter));return `${heading('Service tickets','Search, review, and manage every device in the repair workflow.',role==='Admin'?btn(`${ic('plus')} New service ticket`,'new-ticket','btn-primary'):'')}<div class="toolbar"><div class="field-search">${ic('search')}<input id="table-search" placeholder="Ticket number or customer" value="${esc(filter)}"></div><select class="filter-select" id="status-filter"><option value="All">All</option>${['Received','Under Inspection','Awaiting Estimate','Awaiting Customer Approval','Estimate Rejected','Awaiting Parts','In Repair','Awaiting QC','QC Failed','Ready for Collection','Completed','Cancelled'].map(s=>`<option value="${s}" ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select><select class="filter-select" id="category-filter"><option value="All">All</option>${['Laptop','Smartphone','Desktop PC','Printer','Monitor','Tablet'].map(s=>`<option ${s===categoryFilter?'selected':''}>${s}</option>`).join('')}</select></div><div class="table-card">${table(a,['Ticket / received','Customer','Device','Reported problem','Technician','Status','Expected completion'])}<div class="pagination"><span>Showing ${a.length} of ${S.tickets.length} service tickets</span><div><button disabled>‹</button> <button>1</button> <button disabled>›</button></div></div></div>`}
function intakePage(){return `${heading('New service intake','Capture customer, device, and repair information.',`<button class="btn" data-page="Service Tickets">${ic('back')} Back to tickets</button>`)}<form id="intake-form"><div class="card form-card"><h2 class="section-title"><span>A</span> Customer information</h2><div class="form-grid"><div class="field"><label>Customer name *</label><input required name="customer" placeholder="Full name"></div><div class="field"><label>Phone number *</label><input required name="phone" placeholder="08xx-xxxx-xxxx"></div><div class="field"><label>Email address</label><input name="email" type="email" placeholder="name@email.id"></div><div class="field"><label>Existing customer lookup</label><select name="existing"><option value="">New customer</option>${[...new Set(S.tickets.map(t=>t.customer))].map(n=>`<option>${esc(n)}</option>`).join('')}</select></div></div></div><div class="card form-card"><h2 class="section-title"><span>B</span> Device information</h2><div class="form-grid"><div class="field"><label>Device category *</label><select required name="category"><option value="">Select category</option>${['Laptop','Smartphone','Desktop PC','Printer','Monitor','Tablet','Other'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div><div class="field"><label>Brand *</label><input required name="brand" placeholder="e.g. ASUS"></div><div class="field"><label>Model *</label><input required name="model" placeholder="Model name"></div><div class="field"><label>Serial number</label><input name="serial" placeholder="Serial / IMEI"></div><div class="field"><label>Accessories received</label><input name="accessories" placeholder="Charger, case, cables"></div><div class="field"><label>Physical condition</label><input name="condition" placeholder="Visible marks, cracks, wear"></div><div class="field full"><div class="alert">Record the physical condition above before inspection. Device photos can be attached during in-person intake.</div></div></div></div><div class="card form-card"><h2 class="section-title"><span>C</span> Repair complaint</h2><div class="form-grid"><div class="field full"><label>Customer-reported problem *</label><textarea required name="complaint" placeholder="Describe the issue in the customer's words"></textarea></div><div class="field full"><label>Additional intake notes</label><textarea name="notes" placeholder="Context from the customer"></textarea></div><div class="field full"><label>Initial inspection checklist</label><div style="display:flex;gap:18px;flex-wrap:wrap"><label class="checkline"><input type="checkbox" name="power"> Powers on</label><label class="checkline"><input type="checkbox" name="screen"> Screen checked</label><label class="checkline"><input type="checkbox" name="accessories-check"> Accessories recorded</label><label class="checkline"><input type="checkbox" name="data"> Data backup discussed</label></div></div></div></div><div class="card form-card"><h2 class="section-title"><span>D</span> Service information</h2><div class="form-grid"><div class="field"><label>Priority</label><select name="priority"><option>Normal</option><option>Low</option><option>High</option><option>Urgent</option></select></div><div class="field"><label>Received date</label><input name="received" type="date" value="${D(0)}"></div><div class="field"><label>Estimated completion</label><input name="due" type="date" value="${D(5)}"></div><div class="field"><label>Assigned technician *</label><select required name="tech">${TECHS.map(x=>`<option value="${x}">${x}</option>`).join('')}</select></div></div></div><div class="actions" style="justify-content:flex-end">${btn('Cancel','cancel-intake')}<button class="btn btn-primary" type="submit">Create service ticket ${ic('arrow')}</button></div></form>`}
function stageIndex(s){return s==='Received'?0:['Under Inspection','Awaiting Estimate'].includes(s)?1:['Awaiting Customer Approval','Estimate Rejected','Awaiting Parts'].includes(s)?2:['In Repair','QC Failed'].includes(s)?3:s==='Awaiting QC'?4:['Ready for Collection','Completed'].includes(s)?5:0}function progress(s){let a=['Received','Diagnosis','Estimate','Repair','Quality control','Handover'],i=stageIndex(s);return `<div class="progress">${a.map((x,n)=>`<div class="step ${n<i?'done':n===i?'current':''}"><div class="step-circle">${n<i?'✓':''}</div>${x}</div>`).join('')}</div>`}
function actionBar(t){let a=[];if(role==='Admin'&&t.status==='Awaiting Estimate')a.push(btn('Issue estimate','issue-estimate','btn-primary',`data-ticket-id="${t.id}"`));if(role==='Customer'&&t.customer==='Andi Pratama'&&t.status==='Awaiting Customer Approval')a.push(btn('Reject estimate','reject-estimate','btn-danger',`data-ticket-id="${t.id}"`),btn('Approve estimate','approve-estimate','btn-success',`data-ticket-id="${t.id}"`));if(role==='Technician'&&t.tech===USERS.Technician&&['Received','QC Failed'].includes(t.status))a.push(btn('Open diagnosis','go-diagnosis','btn-primary',`data-ticket-id="${t.id}"`));if(role==='Technician'&&t.tech===USERS.Technician&&t.status==='In Repair')a.push(btn('Open repair workspace','go-repair','btn-primary',`data-ticket-id="${t.id}"`));if(role==='QC'&&t.status==='Awaiting QC')a.push(btn('Inspect device','go-qc','btn-primary',`data-ticket-id="${t.id}"`));if(role==='Admin'&&t.status==='Ready for Collection'&&t.paymentStatus==='Paid')a.push(btn('Record handover','go-handover','btn-primary',`data-ticket-id="${t.id}"`));if(role==='Admin'&&t.estimate>0&&t.qc?.passed&&t.paymentStatus!=='Paid')a.push(btn('Record payment','go-payment','',`data-ticket-id="${t.id}"`));return a.join('')}
function ticketDetail(){let t=byId();if(!t)return `${heading('Ticket not found','Choose a ticket to view details.')}`;let customer=role==='Customer',acts=(t.activities||[]).filter(a=>!customer||/device received|estimate .*issued|estimate .*approved|estimate .*rejected|quality control passed|quality control|handover confirmed|payment received|qc passed|qc failed/i.test(a[1])).slice().reverse();return `${heading('Service ticket details',`Opened ${date(t.received)} · ${t.id}`,`<button class="btn" data-page="${customer?'Track Repair':returnPage||'Service Tickets'}">${ic('back')} Back</button>${actionBar(t)}`)}<div class="detail-layout"><div><div class="card detail-card"><div class="detail-top"><div><div class="detail-id">${t.id}</div><div class="detail-device">${esc(t.brand)} ${esc(t.model)} <span style="color:#a0aaba">· ${esc(t.category)}</span></div></div>${pill(t.status)}</div>${progress(t.status)}<div class="kv-grid"><div><div class="kv-label">Customer</div><div class="kv-value">${esc(t.customer)}</div></div><div><div class="kv-label">Assigned technician</div><div class="kv-value">${esc(t.tech)}</div></div><div><div class="kv-label">Received</div><div class="kv-value">${date(t.received)}</div></div><div><div class="kv-label">Expected completion</div><div class="kv-value">${date(t.due)}</div></div></div></div><div class="card detail-card"><h2 class="section-title">${ic('device')} Device and intake</h2><div class="kv-grid"><div><div class="kv-label">Serial number</div><div class="kv-value">${esc(t.serial||'Not recorded')}</div></div><div><div class="kv-label">Accessories</div><div class="kv-value">${esc(t.accessories||'None')}</div></div><div><div class="kv-label">Priority</div><div class="kv-value">${esc(t.priority)}</div></div><div><div class="kv-label">Condition at intake</div><div class="kv-value">${esc(t.condition||'Not recorded')}</div></div><div style="grid-column:1/-1"><div class="kv-label">Customer complaint</div><div class="kv-value" style="line-height:1.6">${esc(t.complaint)}</div></div></div></div>${t.diagnosis&&!customer?`<div class="card detail-card"><div class="split-head"><h2 class="section-title">Diagnosis and repair notes</h2>${pill(t.decision?'Diagnosis submitted':'Draft diagnosis')}</div><div class="kv-grid"><div><div class="kv-label">Diagnosis</div><div class="kv-value">${esc(t.diagnosis)}</div></div><div><div class="kv-label">Recommended repair</div><div class="kv-value">${esc(t.recommendation||'')}</div></div><div style="grid-column:1/-1"><div class="kv-label">Inspection findings</div><div class="kv-value">${esc(t.findings||'')}</div></div>${t.repairNotes&&!customer?`<div style="grid-column:1/-1"><div class="kv-label">Technician repair notes · internal</div><div class="kv-value">${esc(t.repairNotes)}</div></div>`:''}</div></div>`:''}${t.estimate?`<div class="card detail-card"><div class="split-head"><h2 class="section-title">Repair estimate</h2>${pill(t.decision||'Draft')}</div><div class="mini-stat"><span>Labor</span><strong>${money(t.labor)}</strong></div>${(t.parts||[]).map(p=>`<div class="mini-stat"><span>${esc(p.name)} × ${p.qty}</span><strong>${money(p.qty*p.price)}</strong></div>`).join('')}<div class="mini-stat"><strong>Total estimated</strong><strong style="color:#385bd4">${money(t.estimate)}</strong></div>${t.status==='Awaiting Customer Approval'&&customer?`<div class="alert">Review the breakdown above. Repair begins only after your approval.</div>`:''}${t.status==='Estimate Rejected'?`<div class="alert warn">Estimate rejected${t.decisionReason?': '+esc(t.decisionReason):''}. Ticket cannot proceed to repair.</div>`:''}</div>`:''}${repairJobsPanel(t,customer)}${t.qc?`<div class="card detail-card"><h2 class="section-title">Quality control result ${pill(t.qc.passed?'Passed':'Failed')}</h2><div class="kv-grid"><div><div class="kv-label">Inspected by</div><div class="kv-value">${esc(t.qc.by)}</div></div><div><div class="kv-label">Inspection date</div><div class="kv-value">${date(t.qc.date)}</div></div><div style="grid-column:1/-1"><div class="kv-label">Test notes</div><div class="kv-value">${esc(t.qc.notes)}</div></div></div></div>`:''}</div><div><div class="card detail-card"><h2 class="section-title">${ic('users')} Customer</h2><div class="kv-grid"><div><div class="kv-label">Name</div><div class="kv-value">${esc(t.customer)}</div></div><div><div class="kv-label">Phone</div><div class="kv-value">${customer?'•••• •••• 2230':esc(t.phone)}</div></div><div style="grid-column:1/-1"><div class="kv-label">Email</div><div class="kv-value">${customer?'a••••@email.id':esc(t.email)}</div></div></div></div><div class="card detail-card"><div class="split-head"><h2 class="section-title">${ic('activity')} Activity history</h2><span class="badge gray">${acts.length} events</span></div><div class="timeline">${acts.map(a=>`<div class="timeline-item"><div class="timeline-dot">${ic('check')}</div><div><p><strong>${esc(a[0])}</strong> ${esc(a[1])}</p><time>${date(a[2])}</time></div></div>`).join('')}</div></div><div class="card detail-card"><h2 class="section-title">Payment status</h2><div class="mini-stat"><span>Status</span>${pill(t.paymentStatus)}</div><div class="mini-stat"><span>Amount paid</span><strong>${money(t.payment)}</strong></div><div class="mini-stat"><span>Balance</span><strong>${money(Math.max(0,(t.estimate||0)-t.payment))}</strong></div>${t.warranty?`<div class="mini-stat"><span>Warranty</span><strong>${esc(t.warranty.id)} · until ${date(t.warranty.end)}</strong></div>`:''}</div></div></div>`}
function estimateList(){let a=S.tickets.filter(t=>t.estimate&&t.status!=='Received');return `${heading('Repair estimates','Review diagnosis, issue estimates, and follow customer decisions.') }<div class="table-card">${table(a,['Ticket / received','Customer','Device','Reported problem','Technician','Estimate status','Expected completion'])}</div>`}
function paymentActionMarkup(t){let balance=Math.max(0,Number(t.estimate||0)-Number(t.payment||0));return `<button class="btn btn-sm" data-action="invoice" data-ticket-id="${t.id}">Lihat tagihan</button> ${balance>0?(t.qc?.passed?`<button class="btn btn-primary btn-sm" data-action="go-payment" data-ticket-id="${t.id}">Catat pembayaran</button>`:'<span class="badge amber">Menunggu QC</span>'):'<span class="muted">Lunas</span>'}`}
function paymentPage(){let a=S.tickets.filter(t=>t.estimate>0&&t.decision==='Approved');return `${heading('Payments & invoices','Review approved charges, record payments, and open invoice previews.') }<div class="table-card"><div class="table-wrap"><table class="table"><thead><tr>${['Ticket','Customer','Approved total','Paid','Balance','Payment status','Action'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${a.map(t=>`<tr><td><a class="ticket-id" data-ticket="${t.id}">${t.id}</a></td><td>${esc(t.customer)}</td><td>${money(t.estimate)}</td><td>${money(t.payment)}</td><td>${money(Math.max(0,t.estimate-t.payment))}</td><td>${pill(t.paymentStatus)}</td><td>${paymentActionMarkup(t)}</td></tr>`).join('')}</tbody></table></div></div>`}
function operationQueue(type){let map={jobs:{title:'My repair jobs',desc:'Your assigned tickets, grouped by the next action.',filter:t=>t.tech===USERS.Technician&&!['Completed','Cancelled'].includes(t.status)},diagnosis:{title:'Technician diagnosis',desc:'Inspect assigned devices and submit findings before an estimate is issued.',filter:t=>t.tech===USERS.Technician&&['Received','Under Inspection','QC Failed'].includes(t.status)},repair:{title:'Repair activities',desc:'Work only on customer-approved estimates. Failed QC jobs return here.',filter:t=>t.tech===USERS.Technician&&['In Repair','QC Failed'].includes(t.status)},parts:{title:'Parts used',desc:'Review replacement parts planned and recorded against your jobs.',filter:t=>t.tech===USERS.Technician&&(t.parts||[]).length>0},qc:{title:'QC queue',desc:'Inspect completed repairs before payment and handover.',filter:t=>t.status==='Awaiting QC'},qchistory:{title:'QC history',desc:'Review passed and failed inspection records.',filter:t=>!!t.qc},ready:{title:'Device handover',desc:'Confirm customer acknowledgment after QC pass and full payment.',filter:t=>t.status==='Ready for Collection'},history:{title:'Repair history',desc:'Riwayat tiket yang ditangani oleh teknisi yang sedang masuk.',filter:t=>t.status==='Completed'&&t.tech===USERS.Technician}};let x=map[type],a=S.tickets.filter(x.filter);if(type==='qc')return `${heading(x.title,x.desc)}<div class="table-card">${table(a,['Ticket','Customer','Device','Complaint','Technician','QC status','Due date'])}</div>`;if(type==='parts')return `${heading(x.title,x.desc)}<div class="table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Ticket</th><th>Device</th><th>Part</th><th>Quantity</th><th>Unit cost</th><th>Status</th></tr></thead><tbody>${a.flatMap(t=>t.parts.map(p=>`<tr data-ticket="${t.id}" class="clickable"><td class="ticket-id">${t.id}</td><td>${t.brand} ${t.model}</td><td>${esc(p.name)}</td><td>${p.qty}</td><td>${money(p.price)}</td><td>${t.decision==='Approved'?'Approved estimate':'Proposed'}</td></tr>`)).join('')}</tbody></table></div></div>`;return `${heading(x.title,x.desc)}<div class="table-card">${table(a)}</div>`}
function claimsPage(){let warranties=S.tickets.filter(t=>t.warranty).map(t=>({id:t.warranty.id,ticket:t.id,customer:t.customer,device:`${t.brand} ${t.model}`,start:t.warranty.start,end:t.warranty.end,coverage:t.warranty.coverage}));return `${heading('Warranty management','Review warranty records and make documented decisions on submitted claims.',btn(`${ic('plus')} New claim`,'new-claim','btn-primary'))}<div class="card" style="margin-bottom:14px"><div class="card-head"><h2>Warranty records</h2><span class="badge gray">${warranties.length} records</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Warranty</th><th>Original service</th><th>Customer</th><th>Device</th><th>Start date</th><th>End date</th><th>Status</th><th>Coverage terms</th></tr></thead><tbody>${warranties.map(w=>`<tr><td class="ticket-id">${w.id}</td><td>${w.ticket}</td><td>${esc(w.customer)}</td><td>${esc(w.device)}</td><td>${date(w.start)}</td><td>${date(w.end)}</td><td>${day(w.end)>=0?pill('Active'):pill('Expired')}</td><td>${esc(w.coverage)}</td></tr>`).join('')}</tbody></table></div></div><div class="alert">Eligibility checks support staff review. They do not approve a claim automatically.</div><div class="card"><div class="card-head"><h2>Warranty claims</h2><span class="badge gray">${S.claims.length} claims</span></div><div class="table-wrap"><table class="table"><thead><tr>${['Claim','Customer','Original ticket','Device','Reported issue','Eligibility check','Status','Action'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${S.claims.map(c=>`<tr><td class="ticket-id">${c.id}</td><td>${esc(c.customer)}</td><td>${esc(c.ticket)}</td><td>${esc(c.device)}</td><td>${esc(c.issue)}</td><td>${esc(c.eligibility)}</td><td>${pill(c.status)}</td><td>${role==='Admin'&&!['Resolved','Rejected','Declined by Customer'].includes(c.status)?`<button class="btn btn-sm" data-action="review-claim" data-claim-id="${c.id}">Tinjau</button>`:''}</td></tr>`).join('')}</tbody></table></div></div>`}
function customersPage(){let cs=[...new Map(S.tickets.map(t=>[t.customer,t])).values()];return `${heading('Customers','Customer profiles and linked service history.') }<div class="table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Contact</th><th>Devices serviced</th><th>Open tickets</th><th>Lifetime billed</th><th>Most recent ticket</th></tr></thead><tbody>${cs.map(c=>{let all=S.tickets.filter(t=>t.customer===c.customer);return `<tr><td class="primary-cell">${esc(c.customer)}</td><td>${esc(c.phone)}<div class="sub-cell">${esc(c.email)}</div></td><td>${all.length}</td><td>${all.filter(t=>!['Completed','Cancelled'].includes(t.status)).length}</td><td>${money(all.reduce((n,t)=>n+t.estimate,0))}</td><td><a class="ticket-id" data-ticket="${all[0].id}">${all[0].id}</a></td></tr>`}).join('')}</tbody></table></div></div>`}
let reportRange='Last 30 days';function ownerFilter(){return `<select class="filter-select" id="report-range"><option ${reportRange==='Last 30 days'?'selected':''}>Last 30 days</option><option ${reportRange==='This quarter'?'selected':''}>This quarter</option><option ${reportRange==='This year'?'selected':''}>This year</option><option ${reportRange==='All time'?'selected':''}>All time</option></select>`}
function ownerData(){let cutoff=new Date(D(0)+'T00:00:00');if(reportRange==='Last 30 days')cutoff.setDate(cutoff.getDate()-30);else if(reportRange==='This quarter')cutoff.setMonth(Math.floor(cutoff.getMonth()/3)*3,1);else if(reportRange==='This year')cutoff.setMonth(0,1);else cutoff=new Date(0);let all=S.tickets,a=all.filter(t=>new Date(t.received+'T00:00:00')>=cutoff),completed=a.filter(t=>t.status==='Completed'),active=a.filter(t=>!['Completed','Cancelled'].includes(t.status)),late=a.filter(t=>day(t.due)<0&&!['Completed','Cancelled'].includes(t.status)),rev=a.reduce((n,t)=>n+(t.payment||0),0);return{all,a,completed,active,late,rev}}
function ownerDashboard(){return ownerOverview()}
function ownerOverview(){let{a,completed,active,late,rev}=ownerData(),recent=[...a].sort((x,y)=>y.received.localeCompare(x.received)).slice(0,5),techs=TECHS.map(n=>({n,count:a.filter(t=>t.tech===n&&!['Completed','Cancelled'].includes(t.status)).length,done:a.filter(t=>t.tech===n&&t.status==='Completed').length}));return `${heading('Ringkasan Bisnis','Gambaran singkat kondisi servis dan aktivitas terbaru.',ownerFilter())}<div class="grid metrics owner-metrics">${metric('Tiket masuk',a.length,'Pada periode terpilih','ticket')}${metric('Servis selesai',completed.length,(a.length?Math.round(completed.length/a.length*100):0)+'% dari tiket','check')}${metric('Servis berjalan',active.length,'Masih dalam alur pengerjaan','clock')}${metric('Terlambat',late.length,'Perlu tindak lanjut','activity')}${metric('Pendapatan tercatat',money(rev),'Pembayaran yang sudah masuk','wallet')}${metric('Klaim garansi',S.claims.length,'Semua status klaim','shield')}</div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Distribusi status servis</h2><button data-page="Service Analytics">Analitik servis →</button></div>${distribution(a)}</div><div class="card"><div class="card-head"><h2>Perlu perhatian</h2><span class="badge orange">${late.length} tiket</span></div>${late.length?table(late.slice(0,4)):'<div class="empty-state">Tidak ada tiket terlambat pada periode ini.</div>'}</div></div><div class="grid two-col"><div class="card"><div class="card-head"><h2>Tiket terbaru</h2><button data-page="Service Tickets">Semua tiket →</button></div>${table(recent)}</div><div class="card"><div class="card-head"><h2>Beban teknisi aktif</h2><button data-page="Technician Performance">Lihat kinerja →</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Teknisi</th><th>Berjalan</th><th>Selesai</th></tr></thead><tbody>${techs.map(t=>`<tr><td>${esc(t.n)}</td><td>${t.count}</td><td>${t.done}</td></tr>`).join('')}</tbody></table></div></div></div>`}
function ownerServiceAnalytics(){let{a,all}=ownerData(),cats=[...new Set(a.map(t=>t.category))],catVals=cats.map(c=>Math.round(a.filter(t=>t.category===c).length/Math.max(1,...cats.map(x=>a.filter(t=>t.category===x).length))*100)),weeks=Array.from({length:6},(_,i)=>{let from=new Date(D(-35+7*i)+'T00:00:00'),to=new Date(D(-28+7*i)+'T00:00:00');return a.filter(t=>new Date(t.received+'T00:00:00')>=from&&new Date(t.received+'T00:00:00')<to).length}),max=Math.max(1,...weeks);return `${heading('Analitik Servis','Pola tiket, tahapan pekerjaan, dan kategori perangkat.',ownerFilter())}<div class="grid metrics owner-metrics">${metric('Tiket dalam periode',a.length,'Sesuai filter waktu','ticket')}${metric('Kategori perangkat',cats.length,'Kategori yang tercatat','device')}${metric('Menunggu persetujuan',a.filter(t=>t.status==='Awaiting Customer Approval').length,'Estimasi telah diterbitkan','clock')}${metric('Menunggu QC',a.filter(t=>t.status==='Awaiting QC').length,'Antrean pemeriksaan','check')}</div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Volume tiket per minggu</h2><span class="badge gray">6 minggu terakhir</span></div>${barChart(weeks.map(x=>Math.max(x?12:3,Math.round(x/max*100))),['M−5','M−4','M−3','M−2','M−1','Minggu ini'])}</div><div class="card"><div class="card-head"><h2>Tiket menurut status</h2><span class="badge gray">${a.length} tiket</span></div>${distribution(a)}</div></div><div class="grid two-col"><div class="card"><div class="card-head"><h2>Kategori perangkat</h2></div>${barChart(catVals,cats.map(c=>c.length>15?c.slice(0,13):c))}</div><div class="card"><div class="card-head"><h2>Rincian tiket periode ini</h2></div>${table([...a].sort((x,y)=>y.received.localeCompare(x.received)).slice(0,8))}</div></div><div class="card"><div class="card-head"><h2>Cakupan data</h2><span class="badge blue">${all.length} tiket total</span></div><p class="muted">Grafik dan tabel mengikuti filter periode di kanan atas. Tiket historis tetap tersedia saat memilih “Semua waktu”.</p></div>`}
function ownerRevenueReports(){let{a,rev}=ownerData(),approved=a.filter(t=>t.estimate&&t.decision==='Approved'),billed=approved.reduce((n,t)=>n+t.estimate,0),paid=approved.reduce((n,t)=>n+(t.payment||0),0),balance=Math.max(0,billed-paid),weeks=Array.from({length:6},(_,i)=>{let from=new Date(D(-35+7*i)+'T00:00:00'),to=new Date(D(-28+7*i)+'T00:00:00');return a.filter(t=>new Date(t.received+'T00:00:00')>=from&&new Date(t.received+'T00:00:00')<to).reduce((n,t)=>n+(t.payment||0),0)}),mx=Math.max(1,...weeks);return `${heading('Laporan Pendapatan','Tagihan dari estimasi yang disetujui dan realisasi pembayaran.',ownerFilter())}<div class="grid metrics owner-metrics">${metric('Nilai tagihan disetujui',money(billed),'Estimasi berstatus disetujui','wallet')}${metric('Pembayaran diterima',money(paid),'Dari tiket berestimasi disetujui','check')}${metric('Sisa tagihan',money(balance),'Belum tertagih','clock')}${metric('Pendapatan periode',money(rev),'Seluruh pembayaran tercatat','activity')}</div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Tren pembayaran mingguan</h2><span class="badge green">${money(paid)} diterima</span></div>${barChart(weeks.map(x=>Math.max(x?10:3,Math.round(x/mx*100))),['M−5','M−4','M−3','M−2','M−1','Minggu ini'])}</div><div class="card"><div class="card-head"><h2>Ringkasan status pembayaran</h2></div><div class="mini-stat"><span>Lunas</span><strong>${approved.filter(t=>t.payment>=t.estimate).length} tiket</strong></div><div class="mini-stat"><span>Pembayaran sebagian</span><strong>${approved.filter(t=>t.payment>0&&t.payment<t.estimate).length} tiket</strong></div><div class="mini-stat"><span>Belum membayar</span><strong>${approved.filter(t=>!t.payment).length} tiket</strong></div></div></div><div class="card"><div class="card-head"><h2>Rincian tagihan dan pembayaran</h2><span class="badge gray">${approved.length} estimasi disetujui</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Tiket</th><th>Pelanggan</th><th>Estimasi</th><th>Dibayar</th><th>Sisa</th><th>Status servis</th></tr></thead><tbody>${approved.map(t=>`<tr data-ticket="${t.id}"><td>${esc(t.id)}</td><td>${esc(t.customer)}</td><td>${money(t.estimate)}</td><td>${money(t.payment||0)}</td><td>${money(Math.max(0,t.estimate-(t.payment||0)))}</td><td>${pill(t.status)}</td></tr>`).join('')||'<tr><td colspan="6">Belum ada estimasi disetujui pada periode ini.</td></tr>'}</tbody></table></div></div>`}
function ownerTechnicianPerformance(){let{a}=ownerData(),stats=TECHS.map(n=>{let jobs=a.filter(t=>t.tech===n),done=jobs.filter(t=>t.status==='Completed'),active=jobs.filter(t=>!['Completed','Cancelled'].includes(t.status));let spans=done.filter(t=>t.handover).map(t=>Math.max(1,Math.round((new Date(t.handover)-new Date(t.received))/86400000)));return{n,total:jobs.length,done:done.length,active:active.length,rate:jobs.length?Math.round(done.length/jobs.length*100):0,avg:spans.length?Math.round(spans.reduce((x,y)=>x+y,0)/spans.length):0}});return `${heading('Kinerja Teknisi','Distribusi beban kerja dan penyelesaian per teknisi.',ownerFilter())}<div class="grid metrics owner-metrics">${metric('Teknisi terdaftar',TECHS.length,'Tim servis','users')}${metric('Pekerjaan aktif',stats.reduce((n,t)=>n+t.active,0),'Belum selesai atau dibatalkan','clock')}${metric('Pekerjaan selesai',stats.reduce((n,t)=>n+t.done,0),'Pada periode terpilih','check')}${metric('Rata-rata selesai',stats.length?Math.round(stats.reduce((n,t)=>n+t.avg,0)/stats.length):0,'Hari kalender per teknisi','activity')}</div><div class="grid dash-grid"><div class="card"><div class="card-head"><h2>Beban aktif per teknisi</h2></div>${barChart(stats.map(t=>Math.max(4,Math.round(t.active/Math.max(1,...stats.map(x=>x.active))*100))),stats.map(t=>t.n.split(' ')[0]))}</div><div class="card"><div class="card-head"><h2>Tingkat penyelesaian</h2></div>${barChart(stats.map(t=>Math.max(4,t.rate)),stats.map(t=>t.n.split(' ')[0]))}</div></div><div class="card"><div class="card-head"><h2>Rincian produktivitas</h2><span class="badge gray">${a.length} tiket terfilter</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Teknisi</th><th>Total tiket</th><th>Aktif</th><th>Selesai</th><th>Tingkat selesai</th><th>Rata-rata durasi</th></tr></thead><tbody>${stats.map(t=>`<tr><td>${esc(t.n)}</td><td>${t.total}</td><td>${t.active}</td><td>${t.done}</td><td><div class="track"><div class="fill" style="width:${Math.max(4,t.rate)}%"></div></div> ${t.rate}%</td><td>${t.avg||'—'} hari</td></tr>`).join('')}</tbody></table></div></div>`}
let calendarMonth=new Date();calendarMonth.setDate(1);
function serviceCalendar(){let y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset),tickets=S.tickets.filter(t=>t.due&&t.status!=='Cancelled'),eventsByDay={};for(const t of tickets){let d=new Date(t.due+'T00:00:00');if(d.getFullYear()===y&&d.getMonth()===m)(eventsByDay[d.getDate()]||(eventsByDay[d.getDate()]=[])).push(t)}let cells=Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);let inMonth=d.getMonth()===m,dayEvents=inMonth?(eventsByDay[d.getDate()]||[]):[];return `<div class="calendar-day ${inMonth?'':'outside-month'} ${d.toDateString()===new Date().toDateString()?'today':''}"><span class="calendar-date">${d.getDate()}</span><div class="calendar-events">${dayEvents.map(t=>`<button class="calendar-event ${statusClass(t.status)}" data-action="open-ticket" data-ticket-id="${esc(t.id)}" title="${esc(t.id)} · ${esc(t.customer)} · ${esc(t.brand)} ${esc(t.model)}"><strong>${esc(t.id)}</strong><span>${esc(t.customer)}</span><small>${esc(t.brand)} ${esc(t.model)}</small></button>`).join('')}</div></div>`}).join(''),count=Object.values(eventsByDay).reduce((n,a)=>n+a.length,0),month=new Intl.DateTimeFormat('id-ID',{month:'long',year:'numeric'}).format(first);return `${heading('Jadwal Servis','Pantau target penyelesaian tiket servis berdasarkan tanggal estimasi.',`<button class="btn" data-action="calendar-prev" aria-label="Bulan sebelumnya">${ic('back')}</button><strong class="calendar-month-label">${month}</strong><button class="btn" data-action="calendar-next" aria-label="Bulan berikutnya">${ic('arrow')}</button>`)}<div class="card calendar-card"><div class="calendar-summary"><span>${ic('calendar')} ${count} tiket dengan target pada ${month}</span><span class="calendar-hint">Pilih tiket untuk membuka detail servis</span></div><div class="calendar-grid calendar-weekdays">${['Sen','Sel','Rab','Kam','Jum','Sab','Min'].map(x=>`<div>${x}</div>`).join('')}</div><div class="calendar-grid">${cells}</div></div><div class="calendar-legend"><span><i class="legend-dot amber"></i>Menunggu proses</span><span><i class="legend-dot blue"></i>Sedang dikerjakan</span><span><i class="legend-dot green"></i>Selesai / siap diserahkan</span><span><i class="legend-dot red"></i>Perlu perhatian</span></div>`}
function notificationItems(){let items=[],seen=new Set(S.notificationsSeen||[]),add=(key,title,text,ticket,kind='amber',icon='bell',time='Perlu ditindaklanjuti')=>items.push({key,title,text,ticket,kind,icon,time,unread:!seen.has(key)});if(role==='Admin'){for(const t of S.tickets){let late=day(t.due)<0&&!['Completed','Cancelled'].includes(t.status);if(late)add(`late:${t.id}:${t.due}`,'Tiket melewati target',`${t.customer} · ${t.brand} ${t.model} · target ${date(t.due)}`,t.id,'red','clock',`Terlambat ${Math.abs(day(t.due))} hari`);if(t.status==='Awaiting Estimate')add(`estimate:${t.id}:${t.status}`,'Diagnosis siap diestimasi',`${t.customer} · ${t.brand} ${t.model}`,t.id,'blue','quote');if(t.status==='Awaiting QC')add(`qc:${t.id}:${t.status}`,'Menunggu pemeriksaan mutu',`${t.customer} · ${t.brand} ${t.model}`,t.id,'blue','check');if(t.status==='QC Failed')add(`qcfail:${t.id}:${t.status}`,'Perbaikan perlu ditinjau',`${t.customer} · ${t.brand} ${t.model}`,t.id,'red','activity');if(t.status==='Ready for Collection'&&t.paymentStatus!=='Paid')add(`payment:${t.id}:${t.status}`,'Perangkat siap diserahkan',`${t.customer} · pembayaran ${t.paymentStatus.toLowerCase()}`,t.id,'green','handover')}for(const c of S.claims||[])if(['Submitted','Under Review'].includes(c.status)){let t=S.tickets.find(x=>x.id===c.ticket);if(t)add(`claim:${c.id}:${c.status}`,'Klaim garansi menunggu tinjauan',`${c.id} · ${c.customer} · ${c.device}`,t.id,'amber','shield')}}else if(role==='Technician'){for(const t of S.tickets.filter(t=>t.tech===USERS.Technician&&['Received','QC Failed','Awaiting Parts'].includes(t.status)))add(`job:${t.id}:${t.status}`,'Tiket membutuhkan tindakan',`${t.customer} · ${t.brand} ${t.model} · ${t.status}`,t.id,t.status==='QC Failed'?'red':'blue','wrench')}else if(role==='QC'){for(const t of S.tickets.filter(t=>t.status==='Awaiting QC'))add(`qc:${t.id}:${t.status}`,'Tiket menunggu pemeriksaan',`${t.customer} · ${t.brand} ${t.model}`,t.id,'blue','check')}else if(role==='Customer'){for(const t of S.tickets.filter(t=>t.customer==='Andi Pratama'&&['Awaiting Customer Approval','Ready for Collection','Completed'].includes(t.status)))add(`customer:${t.id}:${t.status}`,'Pembaruan servis',`${t.id} · ${t.status}`,t.id,'blue','ticket')}return items.sort((a,b)=>Number(b.unread)-Number(a.unread)).slice(0,20)}
function unreadNotificationCount(){return notificationItems().filter(n=>n.unread).length}function ownerOperationalReports(){let{a,late}=ownerData(),approval=a.filter(t=>t.status==='Awaiting Customer Approval'),qc=a.filter(t=>t.status==='Awaiting QC'),ready=a.filter(t=>t.status==='Ready for Collection'),attention=[...late,...approval,...qc,...ready].filter((t,i,x)=>x.findIndex(y=>y.id===t.id)===i);return `${heading('Laporan Operasional','Daftar antrean dan pengecualian yang membutuhkan tindak lanjut.',ownerFilter())}<div class="grid metrics owner-metrics">${metric('Terlambat',late.length,'Melewati estimasi selesai','activity')}${metric('Menunggu persetujuan',approval.length,'Menunggu keputusan pelanggan','clock')}${metric('Antrean QC',qc.length,'Menunggu pemeriksaan mutu','check')}${metric('Siap diserahkan',ready.length,'Periksa pembayaran dan serah terima','device')}</div><div class="grid dash-grid operational-report-layout"><div class="card"><div class="card-head"><h2>Tiket perlu tindak lanjut</h2><span class="badge orange">${attention.length} tiket</span></div>${attention.length?table(attention.slice(0,8)):'<div class="empty-state">Tidak ada antrean prioritas saat ini.</div>'}</div><div class="card"><div class="card-head"><h2>Ringkasan antrean</h2></div><div class="mini-stat"><span>Terlambat dari target</span><strong>${late.length}</strong></div><div class="mini-stat"><span>Menunggu keputusan pelanggan</span><strong>${approval.length}</strong></div><div class="mini-stat"><span>Menunggu QC</span><strong>${qc.length}</strong></div><div class="mini-stat"><span>Siap diserahkan</span><strong>${ready.length}</strong></div><div class="mini-stat"><span>Dalam periode terpilih</span><strong>${a.length} tiket</strong></div></div></div><div class="card"><div class="card-head"><h2>Distribusi status operasional</h2></div>${distribution(a)}</div>`}function warrantyCustomer(){let a=S.tickets.filter(t=>t.customer==='Andi Pratama'&&t.warranty);return `${heading('Warranty','Coverage for completed repairs and claim status.')}${a.length?`<div class="table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Warranty</th><th>Original service</th><th>Device</th><th>Start date</th><th>Coverage ends</th><th>Status</th><th>Terms</th></tr></thead><tbody>${a.map(t=>`<tr><td class="ticket-id">${t.warranty.id}</td><td>${t.id}</td><td>${t.brand} ${t.model}</td><td>${date(t.warranty.start)}</td><td>${date(t.warranty.end)}</td><td>${day(t.warranty.end)>=0?pill('Active'):pill('Expired')}</td><td>${esc(t.warranty.coverage)}</td></tr>`).join('')}</tbody></table></div></div>`:`<div class="card empty">Warranty records will appear after a repaired device has passed QC and been handed over.</div>`}<div style="height:14px"></div><div class="card card-body"><div class="split-head"><h2 class="section-title">Warranty claims</h2>${btn('Submit a claim','new-claim','btn-primary')}</div>${S.claims.filter(c=>c.customer==='Andi Pratama').map(c=>`<div class="mini-stat"><span>${c.id} · ${esc(c.issue)}</span>${pill(c.status)}</div>`).join('')||'<div class="empty">No claims submitted.</div>'}</div>`}
function customerHome(){let a=S.tickets.filter(t=>t.customer==='Andi Pratama');return `${heading('Welcome back, Andi','Track your devices and review anything that needs your attention.') }<div class="grid metrics">${metric('My devices',new Set(a.map(t=>t.brand+t.model)).size,'Registered for service','device')}${metric('Active repairs',a.filter(t=>!['Completed','Cancelled'].includes(t.status)).length,'Across current service tickets','wrench')}${metric('Needs your review',a.filter(t=>t.status==='Awaiting Customer Approval').length,'Estimate awaiting a decision','clock')}${metric('Warranty claims',S.claims.filter(c=>c.customer==='Andi Pratama').length,'Submitted claims','shield')}${metric('Paid invoices',a.filter(t=>t.paymentStatus==='Paid').length,'Available in invoices','receipt')}${metric('Completed repairs',a.filter(t=>t.status==='Completed').length,'Repair history','check')}</div><div class="card"><div class="card-head"><h2>Your recent service tickets</h2><button data-page="Track Repair">Track all →</button></div>${table(a)}</div><div class="alert">Your portal only shows your own devices and customer-facing repair information. Technician internal notes are hidden.</div>`}
function deviceTable(arr){return `<div class="table-wrap"><table class="table"><thead><tr><th>Tiket</th><th>Perangkat</th><th>Nomor seri</th><th>Status servis</th><th>Target selesai</th><th>Detail</th></tr></thead><tbody>${arr.map(t=>`<tr><td><a class="ticket-id" data-ticket="${t.id}">${t.id}</a><div class="sub-cell">${date(t.received)}</div></td><td><div class="primary-cell">${esc(t.brand)} ${esc(t.model)}</div><div class="sub-cell">${esc(t.category)}</div></td><td>${esc(t.serial||'Belum dicatat')}</td><td>${pill(t.status)}</td><td>${date(t.due)}</td><td><button class="btn btn-sm" data-ticket="${t.id}">Lihat tiket</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Belum ada perangkat terdaftar.</td></tr>'}</tbody></table></div>`}
function showDeviceRegistration(){openModal('Daftarkan perangkat',`<p class="form-intro">Simpan perangkat milik Anda agar informasi perangkat lebih mudah ditemukan saat mengajukan servis.</p><form id="device-register-form"><div class="form-grid"><div class="field"><label for="device-category">Kategori perangkat *</label><select id="device-category" name="category" required><option value="">Pilih kategori</option><option>Laptop</option><option>Smartphone</option><option>Komputer desktop</option><option>Printer</option><option>Tablet</option><option>Lainnya</option></select></div><div class="field"><label for="device-brand">Merek *</label><input id="device-brand" name="brand" required placeholder="Contoh: ASUS"></div><div class="field"><label for="device-model">Model *</label><input id="device-model" name="model" required placeholder="Contoh: VivoBook 14"></div><div class="field"><label for="device-serial">Nomor seri</label><input id="device-serial" name="serial" placeholder="Opsional"></div><div class="field"><label for="device-purchase-date">Tanggal pembelian</label><input id="device-purchase-date" name="purchaseDate" type="date"></div><div class="field full"><label for="device-notes">Catatan perangkat</label><textarea id="device-notes" name="notes" placeholder="Informasi tambahan (opsional)"></textarea></div></div></form>`,`<button class="btn btn-primary" data-action="save-customer-device">Simpan perangkat</button>`)}
function registeredDeviceTable(devices){return `<div class="table-wrap"><table class="table"><thead><tr><th>Perangkat</th><th>Kategori</th><th>Nomor seri</th><th>Tanggal didaftarkan</th><th>Status</th></tr></thead><tbody>${devices.map(d=>`<tr><td><div class="primary-cell">${esc(d.brand)} ${esc(d.model)}</div><div class="sub-cell">${esc(d.deviceId)}</div></td><td>${esc(d.category)}</td><td>${esc(d.serial||'Belum dicatat')}</td><td>${date(d.registeredOn)}</td><td><span class="badge blue">Terdaftar</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Belum ada perangkat yang didaftarkan.</td></tr>'}</tbody></table></div>`}function customerPage(which){let a=S.tickets.filter(t=>t.customer==='Andi Pratama');if(which==='devices'){let devices=(S.customerDevices||[]).filter(d=>d.customer==='Andi Pratama');return `${heading('Perangkat Saya','Daftarkan dan lihat perangkat yang tersimpan pada akun Anda.',btn(`${ic('plus')} Daftarkan perangkat`,'register-device','btn-primary'))}<div class="card" style="margin-bottom:14px"><div class="card-head"><h2>Perangkat terdaftar</h2><span class="badge blue">${devices.length} perangkat</span></div>${registeredDeviceTable(devices)}</div><div class="card"><div class="card-head"><h2>Perangkat dengan riwayat servis</h2><span class="badge gray">${a.length} tiket</span></div>${deviceTable(a)}</div>`;}if(which==='history')a=a.filter(t=>t.status==='Completed');if(which==='invoice')return `${heading('Invoices','View approved repair charges and payment receipts.') }<div class="table-card"><div class="table-wrap"><table class="table"><thead><tr><th>Invoice / ticket</th><th>Device</th><th>Issued</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th><th></th></tr></thead><tbody>${a.filter(t=>t.estimate>0&&t.decision==='Approved').map(t=>`<tr><td class="ticket-id">INV-${t.id.slice(-3)}<div class="sub-cell">${t.id}</div></td><td>${t.brand} ${t.model}</td><td>${date(t.received)}</td><td>${money(t.estimate)}</td><td>${money(t.payment)}</td><td>${money(Math.max(0,t.estimate-t.payment))}</td><td>${pill(t.paymentStatus)}</td><td><button class="btn btn-sm" data-action="invoice" data-ticket-id="${t.id}">View invoice</button></td></tr>`).join('')}</tbody></table></div></div>`;return `${heading(which==='history'?'Repair history':'Track repair','Follow your repair from intake through handover.') }<div class="table-card">${table(a)}</div>`}
function invoiceView(t){return `<div class="invoice"><div class="invoice-head"><div><div class="invoice-logo">SERASI</div><div class="sub-cell">Service center invoice</div></div><div style="text-align:right"><h2>INVOICE</h2><div class="sub-cell">INV-${t.id.slice(-3)} · ${date(t.received)}</div></div></div><div class="kv-grid" style="margin:20px 0"><div><div class="kv-label">Billed to</div><div class="kv-value">${esc(t.customer)}<br>${esc(t.phone)}<br>${esc(t.email)}</div></div><div><div class="kv-label">Service ticket</div><div class="kv-value">${t.id}<br>${esc(t.brand)} ${esc(t.model)} · ${esc(t.serial)}</div></div></div><div class="mini-stat"><span>Labor · ${esc(t.recommendation||'Repair service')}</span><strong>${money(t.labor)}</strong></div>${(t.parts||[]).map(p=>`<div class="mini-stat"><span>${esc(p.name)} × ${p.qty}</span><strong>${money(p.qty*p.price)}</strong></div>`).join('')}<div class="mini-stat"><strong>Approved total</strong><strong>${money(t.estimate)}</strong></div><div class="invoice-total"><span>Paid: <strong>${money(t.payment)}</strong></span><span>Outstanding: <strong>${money(Math.max(0,t.estimate-t.payment))}</strong></span></div><div class="alert">Final charges match the customer-approved estimate. Payment status: ${t.paymentStatus}.</div><div class="actions" style="justify-content:flex-end;margin-top:20px"><button class="btn" data-action="print">Print invoice</button>${role==='Admin'?btn('Record payment','go-payment','btn-primary',`data-ticket-id="${t.id}"`):''}</div></div>`}
function renderPage(){if(page==='Jadwal Servis'&&role==='Admin')return serviceCalendar();if(page==='Dashboard')return dashboard();if(page==='Service Tickets')return ticketsPage();if(page==='New Intake')return intakePage();if(page==='Ticket Details')return ticketDetail();if(page==='Repair Estimates')return estimateList();if(page==='Payments')return paymentPage();if(page==='Device Handover')return operationQueue('ready');if(page==='Warranty Claims')return claimsPage();if(page==='Customers')return customersPage();if(page==='Overview')return ownerOverview();if(page==='Service Analytics')return ownerServiceAnalytics();if(page==='Revenue Reports')return ownerRevenueReports();if(page==='Technician Performance')return ownerTechnicianPerformance();if(page==='Reports'||page==='Operational Reports')return ownerOperationalReports();if(page==='My Repair Jobs')return operationQueue('jobs');if(page==='Diagnosis')return operationQueue('diagnosis');if(page==='Repair Activities')return operationQueue('repair');if(page==='Parts Used')return operationQueue('parts');if(page==='QC Queue')return operationQueue('qc');if(page==='QC History'||page==='Inspection Details')return operationQueue('qchistory');if(page==='Repair History')return role==='Customer'?customerPage('history'):operationQueue('history');if(page==='My Devices')return customerPage('devices');if(page==='Track Repair')return customerPage('track');if(page==='Invoices')return customerPage('invoice');if(page==='Warranty')return role==='Customer'?warrantyCustomer():claimsPage();if(page==='Invoice Preview')return invoiceView(byId());if(page==='Settings')return `${heading('Pengaturan','Kelola preferensi sistem dan data awal.') }<div class="card detail-card"><h2 class="section-title">Preferensi sistem</h2><div class="mini-stat"><span>Currency</span><strong>Indonesian Rupiah (IDR)</strong></div><div class="mini-stat"><span>Date format</span><strong>DD/MM/YYYY</strong></div><div class="mini-stat"><span>Storage</span><strong>Browser local storage</strong></div><div style="margin-top:15px">${btn('Pulihkan data awal','reset','btn-danger')}</div></div>`;return dashboard()}
