document.addEventListener('submit',onSubmit);document.addEventListener('change',e=>{if(e.target.id==='claim-evidence-input')setClaimEvidence(e.target.files)});document.addEventListener('dragover',e=>{let drop=e.target.closest?.('#claim-evidence-drop');if(drop){e.preventDefault();drop.classList.add('is-dragover')}});document.addEventListener('dragleave',e=>{let drop=e.target.closest?.('#claim-evidence-drop');if(drop&&!drop.contains(e.relatedTarget))drop.classList.remove('is-dragover')});document.addEventListener('drop',e=>{let drop=e.target.closest?.('#claim-evidence-drop');if(drop){e.preventDefault();drop.classList.remove('is-dragover');setClaimEvidence(e.dataTransfer.files)}});
